package com.rmmv.editor.ui.plugin;

import org.json.JSONArray;
import org.json.JSONObject;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * {@code js/plugins.js} reader/writer.
 *
 * <p>The file the RPG Maker editor generates is a single JS assignment:
 * <pre>
 * // Generated by RPG Maker.
 * // Do not edit this file directly.
 * var $plugins =
 * [
 * {"name":"Community_Basic","status":true,...},
 * ...
 * ];
 * </pre>
 *
 * <p>{@link #parse(String)} finds the assignment with a regex, then scans forward
 * to the <em>matching</em> bracket (a regex alone cannot balance nested braces),
 * decodes the literal with org.json, and remembers the surrounding text. A write
 * then touches only the array literal &mdash; the comment header, the variable
 * name and the trailing {@code ;} are preserved byte for byte.
 *
 * <p>Both the variable name used by current RPG Maker MV ({@code $plugins}) and the
 * {@code $dataPlugins} spelling are accepted; {@code $dataPlugins} wins if both appear.
 */
public final class PluginsJs {

    /** {@code var|let|const NAME = [} -- the array may start on a following line. */
    private static final Pattern ASSIGNMENT = Pattern.compile(
            "(?:var|let|const)\\s+(\\$[A-Za-z_$][A-Za-z0-9_$]*)\\s*=\\s*(?=\\[)");

    private static final String PREFERRED = "$dataPlugins";

    /** The file split into "everything before the opening bracket",
     *  the decoded array, and "everything after the matching bracket". */
    public static final class Doc {
        public final String head;
        public final JSONArray array;
        public final String tail;
        public final String variable;
        /** Exact source of the array literal, so an untouched array is written back verbatim. */
        private final String literal;
        /** Canonical form of {@link #literal}, compared against the live array to detect edits. */
        private final String original;

        Doc(String head, JSONArray array, String tail, String variable, String literal) {
            this.head = head;
            this.array = array;
            this.tail = tail;
            this.variable = variable;
            this.literal = literal;
            this.original = array.toString();
        }

        /** Rebuild the file text with the (possibly mutated) array literal. */
        public String render() {
            String body = array.toString().equals(original) ? literal : JsonWrite.pretty(array);
            return head + body + tail;
        }
    }

    private PluginsJs() { }

    /** Parse plugins.js text. Returns null when no array assignment is present. */
    public static Doc parse(String text) {
        if (text == null || text.isEmpty()) return null;
        Matcher m = ASSIGNMENT.matcher(text);
        Doc fallback = null;
        while (m.find()) {
            String variable = m.group(1);
            int open = m.end();                       // position of '[' (end of the match)
            int close = matchBracket(text, open);
            if (close < 0) continue;
            Doc doc = build(text, open, close, variable);
            if (PREFERRED.equals(variable)) return doc;
            if (fallback == null) fallback = doc;
        }
        return fallback;
    }

    private static Doc build(String text, int open, int close, String variable) {
        String literal = text.substring(open, close + 1);
        JSONArray array;
        try {
            array = new JSONArray(literal);
        } catch (Exception e) {
            array = new JSONArray();
        }
        // head stops *before* the '[' and tail starts *after* the matching ']', so
        // head + literal + tail is the original file byte for byte.
        return new Doc(text.substring(0, open), array, text.substring(close + 1),
                variable, literal);
    }

    /**
     * Index of the bracket that closes the '[' at {@code open}, skipping over
     * string literals, line comments and block comments.
     *
     * @return -1 when the literal is unterminated
     */
    static int matchBracket(String s, int open) {
        if (open < 0 || open >= s.length() || s.charAt(open) != '[') return -1;
        int depth = 0;
        boolean inString = false, inLineComment = false, inBlockComment = false;
        for (int i = open; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (inLineComment) {
                if (ch == '\n') inLineComment = false;
                continue;
            }
            if (inBlockComment) {
                if (ch == '*' && i + 1 < s.length() && s.charAt(i + 1) == '/') {
                    inBlockComment = false;
                    i++;
                }
                continue;
            }
            if (inString) {
                if (ch == '\\') { i++; continue; }
                if (ch == '"') inString = false;
                continue;
            }
            if (ch == '"') { inString = true; continue; }
            if (ch == '/' && i + 1 < s.length()) {
                char next = s.charAt(i + 1);
                if (next == '/') { inLineComment = true; i++; continue; }
                if (next == '*') { inBlockComment = true; i++; continue; }
            }
            if (ch == '[') {
                depth++;
            } else if (ch == ']') {
                depth--;
                if (depth == 0) return i;
            }
        }
        return -1;
    }
}